"""
Одна память на все устройства — этап 1 из 3 (память в облаке Supabase).

У каждого устройства остаётся своя копия памяти — Atlas работает так же быстро и без интернета.
Supabase — общий центр: раз в 20 секунд устройство отправляет свои изменения и забирает чужие;
если одно и то же изменили в двух местах — побеждает свежее.

Синхронизируются: факты о тебе (граф), разговоры и их пересказы, карточки SAT/IELTS с историей
повторений, заметки и список дел.

  core/cloud_sync.py        синхронизация (и проверка связи: python core/cloud_sync.py)
  cloud/supabase_setup.sql  таблица в Supabase — выполнить один раз в SQL Editor
  tests/test_cloud_sync.py  9 тестов: два устройства и общее «облако»

Перед установкой memory.db копируется в резервную копию.

    python apply_cloud_memory.py
    python apply_cloud_memory.py --rollback
"""
import os
import re
import shutil
import subprocess
import sys
import time

for _stream in (sys.stdout, sys.stderr):
    try:
        _stream.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass

ROOT = os.path.dirname(os.path.abspath(__file__))
PATCHES = [('main.py', 'при запуске Atlas — фоновая синхронизация памяти (если настроен Supabase)', '    ai_brain.features.start_memory_autoreview()   # раз в 3 дня — проверка памяти, удаление только после «да»\n', '    ai_brain.features.start_memory_autoreview()   # раз в 3 дня — проверка памяти, удаление только после «да»\n    try:\n        from core import cloud_sync                 # одна память на все устройства (если настроен Supabase)\n        cloud_sync.start()\n    except Exception as e:\n        print(f"[облако] синхронизация не запустилась: {e}")\n')]
NEW = {'core/cloud_sync.py': '"""\nОдна память на все устройства.\n\nУ каждого устройства — своя локальная копия (memory.db, atlas_data.json): Atlas работает так же\nбыстро и даже без интернета. Supabase — общий центр: раз в SYNC_EVERY секунд устройство отправляет\nтуда свои изменения и забирает чужие. Если одно и то же изменили в двух местах — побеждает более\nсвежее изменение (у карточек SAT это дата следующего повторения, у фактов — активен ли он).\n\nЧто синхронизируется: граф фактов (nodes, edges), эпизоды и реплики разговоров, карточки и история\nповторений, заметки и дела (atlas_data.json целиком).\n\nКак отслеживаются изменения: в таблицы memory.db добавляются три служебные колонки — uid (общий\nдля всех устройств номер строки), updated_at, dirty — и триггеры, которые их ставят. Код, который\nпишет в память (memory.py, study.py…), менять не нужно.\n\n    SUPABASE_URL, SUPABASE_SERVICE_KEY в .env — без них синхронизация просто выключена.\n    Таблица в Supabase создаётся скриптом cloud/supabase_setup.sql (один раз, в SQL Editor).\n"""\nimport base64\nimport json\nimport os\nimport sqlite3\nimport threading\nimport time\nimport urllib.error\nimport urllib.parse\nimport urllib.request\nimport uuid\nfrom datetime import datetime, timezone\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nDB = os.path.join(ROOT, "memory.db")\nNOTES = os.path.join(ROOT, "atlas_data.json")\nSTATE = os.path.join(ROOT, "cloud_sync_state.json")\nSYNC_EVERY = float(os.getenv("CLOUD_SYNC_EVERY") or 20)\nBATCH = 500\n\n# таблица → колонки (без id), ссылки на другие таблицы, двоичные поля\nSPEC = {\n    "nodes": {"cols": ["name", "label", "emb"], "fk": {}, "blob": ["emb"]},\n    "episodes": {"cols": ["started", "ended", "summary", "emb"], "fk": {}, "blob": ["emb"]},\n    "edges": {"cols": ["src", "rel", "dst", "conf", "updated", "active"], "fk": {"src": "nodes", "dst": "nodes"}, "blob": []},\n    "turns": {"cols": ["ts", "role", "text", "episode"], "fk": {"episode": "episodes"}, "blob": []},\n    "study_cards": {"cols": ["deck", "front", "back", "ease", "interval", "due", "reps", "lapses", "created"],\n                    "fk": {}, "blob": []},\n    "study_reviews": {"cols": ["ts", "card", "grade"], "fk": {"card": "study_cards"}, "blob": []},\n}\nORDER = ["nodes", "episodes", "study_cards", "edges", "turns", "study_reviews"]     # сначала то, на что ссылаются\n\n# те же схемы, что создают memory.py и study.py, — на случай, если таблиц ещё нет\n_SCHEMA = {\n    "turns": "CREATE TABLE IF NOT EXISTS turns (id INTEGER PRIMARY KEY, ts REAL, role TEXT, text TEXT, episode INTEGER)",\n    "episodes": "CREATE TABLE IF NOT EXISTS episodes (id INTEGER PRIMARY KEY, started REAL, ended REAL, summary TEXT, emb BLOB)",\n    "nodes": "CREATE TABLE IF NOT EXISTS nodes (id INTEGER PRIMARY KEY, name TEXT UNIQUE, label TEXT, emb BLOB)",\n    "edges": "CREATE TABLE IF NOT EXISTS edges (id INTEGER PRIMARY KEY, src INTEGER, rel TEXT, dst INTEGER, conf REAL, "\n             "updated REAL, active INTEGER DEFAULT 1)",\n    "study_cards": "CREATE TABLE IF NOT EXISTS study_cards (id INTEGER PRIMARY KEY, deck TEXT, front TEXT, back TEXT, "\n                   "ease REAL DEFAULT 2.5, interval REAL DEFAULT 0, due REAL, reps INTEGER DEFAULT 0, "\n                   "lapses INTEGER DEFAULT 0, created REAL)",\n    "study_reviews": "CREATE TABLE IF NOT EXISTS study_reviews (id INTEGER PRIMARY KEY, ts REAL, card INTEGER, grade INTEGER)",\n}\n_NOW = "((julianday(\'now\') - 2440587.5) * 86400.0)"\n_NEW_UID = "lower(hex(randomblob(16)))"\n_lock = threading.Lock()\n_status = {"on": False, "last": 0.0, "pushed": 0, "pulled": 0, "error": ""}\n\n\n# =============================================================================\n# Облако: Supabase (PostgREST)\n# =============================================================================\nclass SupabaseStore:\n    """push(rows) → сколько принято; pull(since_iso, device) → строки, изменённые другими устройствами."""\n\n    def __init__(self, url: str, key: str, timeout: float = 20):\n        self.url, self.key, self.timeout = url.rstrip("/"), key, timeout\n\n    def _req(self, method, path, body=None):\n        headers = {"apikey": self.key, "Content-Type": "application/json", "Accept": "application/json"}\n        if not self.key.startswith("sb_"):         # старый ключ service_role (eyJ…) — ещё и как Bearer;\n            headers["Authorization"] = f"Bearer {self.key}"   # новый sb_secret_… — только в apikey\n        req = urllib.request.Request(self.url + path, method=method,\n                                     data=json.dumps(body).encode("utf-8") if body is not None else None,\n                                     headers=headers)\n        with urllib.request.urlopen(req, timeout=self.timeout) as r:\n            raw = r.read()\n        return json.loads(raw) if raw else None\n\n    def push(self, rows: list) -> int:\n        return int(self._req("POST", "/rest/v1/rpc/atlas_push", {"rows": rows}) or 0)\n\n    def pull(self, since_iso: str, device: str) -> list:\n        q = urllib.parse.urlencode({"select": "uid,tbl,data,updated_at,deleted,synced_at",\n                                    "synced_at": f"gt.{since_iso}", "device": f"neq.{device}",\n                                    "order": "synced_at.asc", "limit": str(BATCH)})\n        return self._req("GET", f"/rest/v1/atlas_rows?{q}") or []\n\n\ndef store_from_env():\n    url, key = os.getenv("SUPABASE_URL"), os.getenv("SUPABASE_SERVICE_KEY")\n    return SupabaseStore(url, key) if url and key else None\n\n\n# =============================================================================\n# Локальная копия: служебные колонки и триггеры\n# =============================================================================\ndef _connect(db: str):\n    c = sqlite3.connect(db, timeout=30, check_same_thread=False)\n    c.execute("PRAGMA journal_mode=WAL")\n    return c\n\n\ndef prepare(c) -> None:\n    """Один раз (и безопасно повторно): служебные колонки, триггеры, журнал удалений."""\n    c.execute("CREATE TABLE IF NOT EXISTS sync_tombstones (uid TEXT PRIMARY KEY, tbl TEXT, ts REAL)")\n    for t in ORDER:\n        c.execute(_SCHEMA[t])\n        have = {r[1] for r in c.execute(f"PRAGMA table_info({t})")}\n        for col, decl in (("uid", "TEXT"), ("updated_at", "REAL"), ("dirty", "INTEGER DEFAULT 0")):\n            if col not in have:\n                c.execute(f"ALTER TABLE {t} ADD COLUMN {col} {decl}")\n        # всё, что было до синхронизации, — свои изменения: отправить\n        c.execute(f"UPDATE {t} SET uid={_NEW_UID}, updated_at={_NOW}, dirty=1 WHERE uid IS NULL")\n        c.execute(f"CREATE UNIQUE INDEX IF NOT EXISTS {t}_uid ON {t}(uid)")\n        # новая строка от программы (uid пустой) — получает uid и помечается «отправить»;\n        # строка из облака приходит уже с uid — её не трогаем\n        c.execute(f"CREATE TRIGGER IF NOT EXISTS {t}_sync_ins AFTER INSERT ON {t} WHEN NEW.uid IS NULL BEGIN "\n                  f"UPDATE {t} SET uid={_NEW_UID}, updated_at={_NOW}, dirty=1 WHERE rowid=NEW.rowid; END")\n        # правка программой (updated_at и dirty не меняла) — «отправить»; правки синхронизации меняют\n        # updated_at или dirty и триггер не задевают\n        c.execute(f"CREATE TRIGGER IF NOT EXISTS {t}_sync_upd AFTER UPDATE ON {t} "\n                  f"WHEN NEW.updated_at IS OLD.updated_at AND NEW.dirty IS OLD.dirty BEGIN "\n                  f"UPDATE {t} SET updated_at={_NOW}, dirty=1 WHERE rowid=NEW.rowid; END")\n        # удаление программой — в журнал удалений; удаление синхронизацией (dirty=-1) — нет\n        c.execute(f"CREATE TRIGGER IF NOT EXISTS {t}_sync_del AFTER DELETE ON {t} "\n                  f"WHEN OLD.uid IS NOT NULL AND OLD.dirty >= 0 BEGIN "\n                  f"INSERT OR REPLACE INTO sync_tombstones (uid, tbl, ts) VALUES (OLD.uid, \'{t}\', {_NOW}); END")\n    c.commit()\n\n\n# =============================================================================\n# Отправка\n# =============================================================================\ndef _uid_of(c, table: str, local_id):\n    if local_id in (None, 0):\n        return None\n    r = c.execute(f"SELECT uid FROM {table} WHERE id=?", (local_id,)).fetchone()\n    return r[0] if r else None\n\n\ndef _encode(c, t: str, row: dict) -> dict:\n    spec, data = SPEC[t], {}\n    for col in spec["cols"]:\n        v = row[col]\n        if col in spec["blob"]:\n            data[col] = base64.b64encode(v).decode("ascii") if v is not None else None\n        elif col in spec["fk"]:\n            data[col + "_uid"] = _uid_of(c, spec["fk"][col], v)\n            if t == "edges":                       # имя узла — запасной способ найти его на другом устройстве\n                n = c.execute("SELECT name, label FROM nodes WHERE id=?", (v,)).fetchone()\n                data[col + "_name"], data[col + "_label"] = (n[0], n[1]) if n else (None, None)\n        else:\n            data[col] = v\n    return data\n\n\ndef _collect(c, device: str) -> list:\n    out = []\n    for t in ORDER:\n        cols = ", ".join(["uid", "updated_at"] + SPEC[t]["cols"])\n        for r in c.execute(f"SELECT {cols} FROM {t} WHERE dirty=1"):\n            row = dict(zip(["uid", "updated_at"] + SPEC[t]["cols"], r))\n            out.append({"uid": row["uid"], "tbl": t, "data": _encode(c, t, row),\n                        "updated_at": row["updated_at"], "deleted": False, "device": device})\n    for uid, t, ts in c.execute("SELECT uid, tbl, ts FROM sync_tombstones"):\n        out.append({"uid": uid, "tbl": t, "data": {}, "updated_at": ts, "deleted": True, "device": device})\n    return out\n\n\ndef _mark_sent(c, rows: list) -> None:\n    for r in rows:\n        if r["deleted"]:\n            c.execute("DELETE FROM sync_tombstones WHERE uid=? AND ts=?", (r["uid"], r["updated_at"]))\n        elif r["tbl"] in SPEC:\n            # только если с тех пор не меняли — иначе уйдёт в следующий раз\n            c.execute(f"UPDATE {r[\'tbl\']} SET dirty=0 WHERE uid=? AND updated_at=?", (r["uid"], r["updated_at"]))\n    c.commit()\n\n\n# =============================================================================\n# Приём\n# =============================================================================\ndef _local_id(c, table: str, uid):\n    if not uid:\n        return None\n    r = c.execute(f"SELECT id FROM {table} WHERE uid=?", (uid,)).fetchone()\n    return r[0] if r else None\n\n\ndef _node_id(c, uid, name, label):\n    """Узел по uid; иначе по имени (один и тот же человек/предмет, созданный на двух устройствах)."""\n    nid = _local_id(c, "nodes", uid)\n    if nid or not name:\n        return nid\n    r = c.execute("SELECT id FROM nodes WHERE name=?", (name,)).fetchone()\n    if r:\n        return r[0]\n    return c.execute("INSERT INTO nodes (name, label, uid, updated_at, dirty) VALUES (?,?,?,?,0)",\n                     (name, label or name, uid or uuid.uuid4().hex, time.time())).lastrowid\n\n\ndef _decode(c, t: str, data: dict) -> dict:\n    spec, row = SPEC[t], {}\n    for col in spec["cols"]:\n        if col in spec["blob"]:\n            v = data.get(col)\n            row[col] = base64.b64decode(v) if v else None\n        elif col in spec["fk"]:\n            target = spec["fk"][col]\n            if target == "nodes":\n                row[col] = _node_id(c, data.get(col + "_uid"), data.get(col + "_name"), data.get(col + "_label"))\n            else:\n                row[col] = _local_id(c, target, data.get(col + "_uid")) or (0 if col == "episode" and\n                                                                            data.get(col + "_uid") is None else None)\n        else:\n            row[col] = data.get(col)\n    return row\n\n\ndef _apply(c, item: dict) -> bool:\n    """Изменение из облака → в локальную копию. Своё более свежее изменение не перетирается."""\n    t, uid, ts = item["tbl"], item["uid"], float(item["updated_at"])\n    if t not in SPEC:\n        return False\n    local = c.execute(f"SELECT id, updated_at FROM {t} WHERE uid=?", (uid,)).fetchone()\n    if local and (local[1] or 0) >= ts:\n        return False\n    if item.get("deleted"):\n        if local:\n            c.execute(f"UPDATE {t} SET dirty=-1 WHERE id=?", (local[0],))\n            c.execute(f"DELETE FROM {t} WHERE id=?", (local[0],))\n        return bool(local)\n    row = _decode(c, t, item.get("data") or {})\n    if t == "nodes" and not local:\n        same = c.execute("SELECT id, uid FROM nodes WHERE name=?", (row["name"],)).fetchone()\n        if same:                                   # один узел, созданный на двух устройствах: берём меньший uid\n            if uid < (same[1] or "~"):\n                c.execute("UPDATE nodes SET uid=?, updated_at=?, dirty=0 WHERE id=?", (uid, ts, same[0]))\n            return False\n    cols = SPEC[t]["cols"]\n    if local:\n        c.execute(f"UPDATE {t} SET {\', \'.join(f\'{k}=?\' for k in cols)}, updated_at=?, dirty=0 WHERE id=?",\n                  [row[k] for k in cols] + [ts, local[0]])\n    else:\n        c.execute(f"INSERT INTO {t} ({\', \'.join(cols)}, uid, updated_at, dirty) VALUES ({\', \'.join(\'?\' * len(cols))},?,?,0)",\n                  [row[k] for k in cols] + [uid, ts])\n    return True\n\n\n# =============================================================================\n# Заметки и дела: atlas_data.json одним документом\n# =============================================================================\ndef _notes_item(state: dict, device: str):\n    if not os.path.exists(NOTES):\n        return None\n    mtime = os.path.getmtime(NOTES)\n    if mtime <= state.get("notes_sent", 0):\n        return None\n    with open(NOTES, encoding="utf-8") as f:\n        content = f.read()\n    return {"uid": "kv:notes", "tbl": "kv", "data": {"json": content}, "updated_at": mtime, "deleted": False,\n            "device": device}\n\n\ndef _apply_notes(item: dict, state: dict) -> bool:\n    ts = float(item["updated_at"])\n    if os.path.exists(NOTES) and os.path.getmtime(NOTES) >= ts:\n        return False\n    with open(NOTES, "w", encoding="utf-8") as f:\n        f.write((item.get("data") or {}).get("json") or \'{"notes": [], "todos": []}\')\n    os.utime(NOTES, (ts, ts))                      # время из облака — чтобы не отправить обратно\n    state["notes_sent"] = ts\n    return True\n\n\n# =============================================================================\n# Один круг синхронизации\n# =============================================================================\ndef _load_state() -> dict:\n    try:\n        with open(STATE, encoding="utf-8") as f:\n            return json.load(f)\n    except Exception:\n        return {}\n\n\ndef _save_state(state: dict) -> None:\n    with open(STATE, "w", encoding="utf-8") as f:\n        json.dump(state, f)\n\n\ndef _ts(iso: str) -> float:\n    """Время из ответа Supabase («2026-10-06T09:00:00.123456+00:00», бывает с «Z») → секунды."""\n    return datetime.fromisoformat(str(iso).replace("Z", "+00:00")).timestamp()\n\n\ndef _iso(ts: float) -> str:\n    return datetime.fromtimestamp(ts, tz=timezone.utc).isoformat()\n\n\ndef sync_once(store, db: str = None) -> dict:\n    """Отправить своё, забрать чужое. → {\'pushed\': n, \'pulled\': n}."""\n    state = _load_state()\n    device = state.setdefault("device", uuid.uuid4().hex[:12])\n    with _lock:\n        c = _connect(db or DB)\n        try:\n            prepare(c)\n            rows = _collect(c, device)\n            note = _notes_item(state, device)\n            if note:\n                rows.append(note)\n            for i in range(0, len(rows), BATCH):\n                part = rows[i:i + BATCH]\n                store.push(part)\n                _mark_sent(c, part)\n                if note in part:\n                    state["notes_sent"] = note["updated_at"]\n            pulled, cursor = 0, state.get("pulled_until", "1970-01-01T00:00:00+00:00")\n            while True:\n                # с небольшим нахлёстом: изменения, записанные одновременно, не теряются\n                since = _iso(max(0.0, _ts(cursor) - 5))\n                items = store.pull(since, device)\n                fresh = [it for it in items if _ts(it["synced_at"]) > _ts(cursor)]\n                for it in items:\n                    if it["tbl"] == "kv" and it["uid"] == "kv:notes":\n                        pulled += _apply_notes(it, state)\n                    else:\n                        pulled += _apply(c, it)\n                c.commit()\n                if not fresh:\n                    break\n                cursor = max((it["synced_at"] for it in fresh), key=_ts)\n                if len(items) < BATCH:\n                    break\n            state["pulled_until"] = cursor\n        finally:\n            c.close()\n        _save_state(state)\n    if pulled:\n        try:                                       # кэши памяти пересоберутся с новыми данными\n            from core import memory\n            memory._graph["dirty"] = True\n            memory._cache["dirty"] = True\n        except Exception:\n            pass\n    return {"pushed": len(rows), "pulled": pulled}\n\n\ndef status() -> dict:\n    return dict(_status)\n\n\ndef start() -> bool:\n    """Фоновая синхронизация, если в .env есть ключи Supabase."""\n    store = store_from_env()\n    if store is None:\n        print("[облако] синхронизация памяти выключена: нет SUPABASE_URL / SUPABASE_SERVICE_KEY в .env")\n        return False\n    _status["on"] = True\n\n    def loop():\n        while True:\n            try:\n                r = sync_once(store)\n                _status.update(last=time.time(), error="", pushed=_status["pushed"] + r["pushed"],\n                               pulled=_status["pulled"] + r["pulled"])\n                if r["pushed"] or r["pulled"]:\n                    print(f"[облако] память: отправлено {r[\'pushed\']}, получено {r[\'pulled\']}")\n            except urllib.error.HTTPError as e:\n                _status["error"] = f"{e.code}: {e.read()[:200].decode(\'utf-8\', \'replace\')}"\n                print(f"[облако] Supabase ответил ошибкой {_status[\'error\']}")\n            except Exception as e:\n                _status["error"] = str(e)[:200]\n                print(f"[облако] нет связи с Supabase ({e}) — память работает локально, попробую позже")\n            time.sleep(SYNC_EVERY)\n    threading.Thread(target=loop, daemon=True, name="cloud-sync").start()\n    print("[облако] синхронизация памяти включена")\n    return True\n\n\nif __name__ == "__main__":\n    # python core/cloud_sync.py — проверить связь с Supabase и синхронизировать память один раз\n    for _stream in (__import__("sys").stdout, __import__("sys").stderr):\n        try:\n            _stream.reconfigure(encoding="utf-8", errors="replace")\n        except Exception:\n            pass\n    try:\n        from dotenv import load_dotenv\n        load_dotenv(os.path.join(ROOT, ".env"))\n    except Exception:\n        pass\n    st = store_from_env()\n    if st is None:\n        print("Нет SUPABASE_URL или SUPABASE_SERVICE_KEY в .env — см. инструкцию.")\n        raise SystemExit(1)\n    try:\n        r = sync_once(st)\n    except urllib.error.HTTPError as e:\n        body = e.read()[:300].decode("utf-8", "replace")\n        hint = (" — похоже, не выполнен cloud/supabase_setup.sql" if e.code == 404 or "atlas_" in body\n                else " — проверь ключ: нужен service_role, а не anon" if e.code in (401, 403) else "")\n        print(f"✗ Supabase ответил ошибкой {e.code}: {body}{hint}")\n        raise SystemExit(1)\n    except Exception as e:\n        print(f"✗ Нет связи с Supabase: {e}")\n        raise SystemExit(1)\n    print(f"✓ Связь с Supabase есть. Отправлено: {r[\'pushed\']}, получено: {r[\'pulled\']}.")\n', 'cloud/supabase_setup.sql': "-- Atlas: одна память на все устройства.\n-- Выполнить один раз: Supabase → SQL Editor → New query → вставить этот текст → Run.\n\n-- Все строки памяти всех устройств в одной таблице: какая таблица (tbl), содержимое (data),\n-- когда изменено на устройстве (updated_at) и когда попало в облако (synced_at).\ncreate table if not exists public.atlas_rows (\n  uid        text primary key,\n  tbl        text not null,\n  data       jsonb not null default '{}'::jsonb,\n  updated_at double precision not null,\n  deleted    boolean not null default false,\n  device     text,\n  synced_at  timestamptz not null default clock_timestamp()\n);\ncreate index if not exists atlas_rows_synced_at on public.atlas_rows (synced_at);\n\n-- Закрыть таблицу для всех, кроме секретного ключа service_role (он хранится только на компьютере\n-- и в облачном мозге Atlas, никогда на телефоне). Политик нет — значит, обычным ключом не прочитать.\nalter table public.atlas_rows enable row level security;\n\n-- Приём изменений: если строку уже меняли на другом устройстве позже — свежее не перетирается.\ncreate or replace function public.atlas_push(rows jsonb)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare n integer;\nbegin\n  insert into atlas_rows (uid, tbl, data, updated_at, deleted, device, synced_at)\n  select r->>'uid', r->>'tbl', coalesce(r->'data', '{}'::jsonb), (r->>'updated_at')::double precision,\n         coalesce((r->>'deleted')::boolean, false), r->>'device', clock_timestamp()\n  from jsonb_array_elements(rows) as r\n  on conflict (uid) do update\n    set tbl = excluded.tbl, data = excluded.data, updated_at = excluded.updated_at,\n        deleted = excluded.deleted, device = excluded.device, synced_at = clock_timestamp()\n    where excluded.updated_at > atlas_rows.updated_at;\n  get diagnostics n = row_count;\n  return n;\nend\n$$;\n\nrevoke all on function public.atlas_push(jsonb) from public, anon, authenticated;\ngrant execute on function public.atlas_push(jsonb) to service_role;\n", 'tests/test_cloud_sync.py': '"""\nТесты одной памяти на все устройства (core/cloud_sync.py).\n\n    python tests/test_cloud_sync.py\n\nДва «устройства» — две отдельные базы memory.db и два файла заметок; «облако» — подставное, но\nведёт себя как таблица Supabase из cloud/supabase_setup.sql: принимает только более свежие изменения\nи отдаёт их по времени попадания в облако. Последний тест проверяет настоящие HTTP-запросы.\n"""\nimport http.server\nimport importlib.util\nimport json\nimport os\nimport sqlite3\nimport sys\nimport tempfile\nimport threading\nimport time\nimport traceback\nfrom datetime import datetime, timedelta, timezone\n\nfor _stream in (sys.stdout, sys.stderr):\n    try:\n        _stream.reconfigure(encoding="utf-8", errors="replace")\n    except Exception:\n        pass\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nspec = importlib.util.spec_from_file_location("cloud_sync", os.path.join(ROOT, "core", "cloud_sync.py"))\nCS = importlib.util.module_from_spec(spec)\nspec.loader.exec_module(CS)\n\n\nclass FakeCloud:\n    """Как atlas_rows + atlas_push в Supabase."""\n\n    def __init__(self):\n        self.rows, self.clock, self.down = {}, datetime(2026, 10, 6, tzinfo=timezone.utc), False\n\n    def _tick(self):\n        self.clock += timedelta(milliseconds=1)\n        return self.clock.isoformat()\n\n    def push(self, rows):\n        if self.down:\n            raise OSError("нет сети")\n        n = 0\n        for r in rows:\n            cur = self.rows.get(r["uid"])\n            if cur is None or r["updated_at"] > cur["updated_at"]:\n                self.rows[r["uid"]] = dict(r, synced_at=self._tick())\n                n += 1\n        return n\n\n    def pull(self, since_iso, device):\n        if self.down:\n            raise OSError("нет сети")\n        since = datetime.fromisoformat(since_iso)\n        got = [r for r in self.rows.values()\n               if datetime.fromisoformat(r["synced_at"]) > since and r.get("device") != device]\n        return sorted(got, key=lambda r: r["synced_at"])[:CS.BATCH]\n\n\nclass Device:\n    def __init__(self, name):\n        d = tempfile.mkdtemp(prefix=f"atlas_{name}_")\n        self.db, self.state, self.notes = (os.path.join(d, "memory.db"), os.path.join(d, "state.json"),\n                                           os.path.join(d, "atlas_data.json"))\n        c = sqlite3.connect(self.db)\n        for sql in CS._SCHEMA.values():\n            c.execute(sql)\n        c.commit()\n        c.close()\n\n    def sync(self, cloud):\n        CS.STATE, CS.NOTES = self.state, self.notes\n        return CS.sync_once(cloud, self.db)\n\n    def sql(self, q, args=()):\n        c = sqlite3.connect(self.db)\n        try:\n            r = c.execute(q, args).fetchall()\n            c.commit()\n            return r\n        finally:\n            c.close()\n\n    # как это делают memory.py и study.py\n    def node(self, label):\n        name = label.lower()\n        r = self.sql("SELECT id FROM nodes WHERE name=?", (name,))\n        if r:\n            return r[0][0]\n        self.sql("INSERT INTO nodes (name, label, emb) VALUES (?,?,?)", (name, label, b"\\x00\\x00\\x80\\x3f" * 4))\n        return self.sql("SELECT id FROM nodes WHERE name=?", (name,))[0][0]\n\n    def fact(self, s, r, o, single=True):\n        sid, oid = self.node(s), self.node(o)\n        if single:\n            self.sql("UPDATE edges SET active=0 WHERE src=? AND rel=? AND active=1", (sid, r))\n        self.sql("INSERT INTO edges (src, rel, dst, conf, updated) VALUES (?,?,?,?,?)", (sid, r, oid, 0.8, time.time()))\n\n    def facts(self):\n        return sorted(self.sql("SELECT s.label, e.rel, d.label FROM edges e JOIN nodes s ON s.id=e.src "\n                               "JOIN nodes d ON d.id=e.dst WHERE e.active=1"))\n\n\nTESTS = []\n\n\ndef test(fn):\n    TESTS.append(fn)\n    return fn\n\n\n@test\ndef existing_memory_is_uploaded_once():\n    cloud, a = FakeCloud(), Device("a")\n    a.fact("User", "prepares_for", "SAT")\n    a.sql("INSERT INTO turns (ts, role, text) VALUES (?,?,?)", (time.time(), "user", "привет"))\n    r1 = a.sync(cloud)\n    assert r1["pushed"] == 4 and len(cloud.rows) == 4, (r1, len(cloud.rows))   # 2 узла, связь, реплика\n    assert a.sync(cloud)["pushed"] == 0, "второй раз отправлять нечего"\n\n\n@test\ndef facts_and_conversations_arrive_with_links_intact():\n    cloud, a, b = FakeCloud(), Device("a"), Device("b")\n    a.fact("User", "lives_in", "Bishkek")\n    a.fact("User", "exam_date", "2026-12-05")\n    a.sql("INSERT INTO episodes (started, ended, summary, emb) VALUES (1,2,\'Обсуждали SAT\',?)", (b"\\x01" * 16,))\n    ep = a.sql("SELECT id FROM episodes")[0][0]\n    a.sql("INSERT INTO turns (ts, role, text, episode) VALUES (1,\'user\',\'как подготовиться к SAT?\',?)", (ep,))\n    a.sync(cloud)\n    b.sync(cloud)\n    assert b.facts() == a.facts(), (b.facts(), a.facts())\n    assert b.sql("SELECT t.text, e.summary FROM turns t JOIN episodes e ON e.id=t.episode") == \\\n        [("как подготовиться к SAT?", "Обсуждали SAT")]\n    assert b.sql("SELECT emb FROM episodes")[0][0] == b"\\x01" * 16, "вектор смысла дошёл без искажений"\n\n\n@test\ndef same_person_created_on_both_devices_is_one_node():\n    cloud, a, b = FakeCloud(), Device("a"), Device("b")\n    a.fact("User", "likes", "jazz", single=False)\n    b.fact("User", "studies_at", "School 61")                       # «User» создан и на втором устройстве\n    a.sync(cloud), b.sync(cloud), a.sync(cloud), b.sync(cloud)\n    for d in (a, b):\n        assert d.sql("SELECT COUNT(*) FROM nodes WHERE name=\'user\'")[0][0] == 1\n        assert d.facts() == [("User", "likes", "jazz"), ("User", "studies_at", "School 61")], d.facts()\n\n\n@test\ndef study_progress_follows_you_between_devices():\n    cloud, a, b = FakeCloud(), Device("a"), Device("b")\n    a.sql("INSERT INTO study_cards (deck, front, back, due, created) VALUES (\'SAT\',\'ubiquitous\',\'вездесущий\',?,?)",\n          (time.time(), time.time()))\n    a.sync(cloud), b.sync(cloud)\n    card = b.sql("SELECT id FROM study_cards")[0][0]\n    time.sleep(0.01)\n    b.sql("UPDATE study_cards SET interval=3, reps=2, due=? WHERE id=?", (time.time() + 3 * 86400, card))  # повторил на телефоне\n    b.sql("INSERT INTO study_reviews (ts, card, grade) VALUES (?,?,5)", (time.time(), card))\n    b.sync(cloud), a.sync(cloud)\n    assert a.sql("SELECT interval, reps FROM study_cards") == [(3.0, 2)]\n    assert a.sql("SELECT r.grade, c.front FROM study_reviews r JOIN study_cards c ON c.id=r.card") == [(5, "ubiquitous")]\n\n\n@test\ndef newer_change_wins_on_both_devices():\n    cloud, a, b = FakeCloud(), Device("a"), Device("b")\n    a.sql("INSERT INTO study_cards (deck, front, back, due, created) VALUES (\'SAT\',\'arcane\',\'тайный\',0,0)")\n    a.sync(cloud), b.sync(cloud)\n    b.sql("UPDATE study_cards SET reps=1")                            # раньше\n    time.sleep(0.02)\n    a.sql("UPDATE study_cards SET reps=7")                            # позже — этот должен победить\n    b.sync(cloud), a.sync(cloud), b.sync(cloud)\n    assert a.sql("SELECT reps FROM study_cards") == [(7,)] and b.sql("SELECT reps FROM study_cards") == [(7,)]\n\n\n@test\ndef deletions_and_forgotten_facts_spread_without_echo():\n    cloud, a, b = FakeCloud(), Device("a"), Device("b")\n    a.sql("INSERT INTO study_cards (deck, front, back, due, created) VALUES (\'Old\',\'x\',\'y\',0,0)")\n    a.fact("User", "likes", "Iron Man 3", single=False)\n    a.sync(cloud), b.sync(cloud)\n    a.sql("DELETE FROM study_cards WHERE deck=\'Old\'")                 # удалил колоду\n    a.sql("UPDATE edges SET active=0")                               # «проверь память» убрал мусор\n    a.sync(cloud), b.sync(cloud)\n    assert b.sql("SELECT COUNT(*) FROM study_cards")[0][0] == 0 and b.facts() == []\n    assert b.sql("SELECT COUNT(*) FROM sync_tombstones")[0][0] == 0, "удаление из облака не уходит обратно"\n    assert b.sync(cloud)["pushed"] == 0 and a.sync(cloud)["pushed"] == 0, "никакого эха"\n\n\n@test\ndef notes_and_todos_are_shared():\n    cloud, a, b = FakeCloud(), Device("a"), Device("b")\n    with open(a.notes, "w", encoding="utf-8") as f:\n        json.dump({"notes": ["купить молоко"], "todos": []}, f, ensure_ascii=False)\n    a.sync(cloud), b.sync(cloud)\n    assert json.load(open(b.notes, encoding="utf-8"))["notes"] == ["купить молоко"]\n    time.sleep(0.02)\n    with open(b.notes, "w", encoding="utf-8") as f:\n        json.dump({"notes": ["купить молоко"], "todos": [{"task": "SAT тест", "done": False}]}, f, ensure_ascii=False)\n    b.sync(cloud), a.sync(cloud)\n    assert json.load(open(a.notes, encoding="utf-8"))["todos"][0]["task"] == "SAT тест"\n    assert a.sync(cloud)["pushed"] == 0 and b.sync(cloud)["pushed"] == 0, "заметки не ходят туда-обратно"\n\n\n@test\ndef offline_nothing_is_lost():\n    cloud, a, b = FakeCloud(), Device("a"), Device("b")\n    a.fact("User", "goal", "IELTS 7.5")\n    cloud.down = True\n    try:\n        a.sync(cloud)\n        assert False, "без сети синхронизация должна сообщить об ошибке"\n    except OSError:\n        pass\n    assert a.facts() == [("User", "goal", "IELTS 7.5")], "локальная память цела"\n    cloud.down = False\n    a.sync(cloud), b.sync(cloud)\n    assert b.facts() == [("User", "goal", "IELTS 7.5")], "отправилось, когда сеть вернулась"\n\n\n@test\ndef real_http_requests_to_supabase():\n    seen = []\n\n    class H(http.server.BaseHTTPRequestHandler):\n        def log_message(self, *a):\n            pass\n\n        def _reply(self, obj):\n            body = json.dumps(obj).encode()\n            self.send_response(200)\n            self.send_header("Content-Type", "application/json")\n            self.send_header("Content-Length", str(len(body)))\n            self.end_headers()\n            self.wfile.write(body)\n\n        def do_POST(self):\n            n = int(self.headers.get("Content-Length") or 0)\n            seen.append(("POST", self.path, {k.lower(): v for k, v in self.headers.items()}, json.loads(self.rfile.read(n))))\n            self._reply(1)\n\n        def do_GET(self):\n            seen.append(("GET", self.path, {k.lower(): v for k, v in self.headers.items()}, None))\n            self._reply([])\n\n    srv = http.server.HTTPServer(("127.0.0.1", 0), H)\n    threading.Thread(target=srv.serve_forever, daemon=True).start()\n    try:\n        st = CS.SupabaseStore(f"http://127.0.0.1:{srv.server_port}/", "secret-key")\n        assert st.push([{"uid": "u1", "tbl": "nodes", "data": {}, "updated_at": 1.0, "deleted": False, "device": "d"}]) == 1\n        assert st.pull("2026-10-06T00:00:00+00:00", "d") == []\n    finally:\n        srv.shutdown()\n    (m1, p1, h1, b1), (m2, p2, h2, _) = seen\n    assert m1 == "POST" and p1 == "/rest/v1/rpc/atlas_push" and b1["rows"][0]["uid"] == "u1"\n    assert h1["apikey"] == "secret-key" and h1["authorization"] == "Bearer secret-key"\n    assert m2 == "GET" and p2.startswith("/rest/v1/atlas_rows?") and "device=neq.d" in p2 and "synced_at=gt." in p2, p2\n    seen.clear()\n    srv2 = http.server.HTTPServer(("127.0.0.1", 0), H)\n    threading.Thread(target=srv2.serve_forever, daemon=True).start()\n    try:\n        CS.SupabaseStore(f"http://127.0.0.1:{srv2.server_port}", "sb_secret_abc").pull("2026-10-06T00:00:00+00:00", "d")\n    finally:\n        srv2.shutdown()\n    assert seen[0][2]["apikey"] == "sb_secret_abc" and "authorization" not in seen[0][2], "новый ключ — только в apikey"\n\n\ndef main():\n    ok = 0\n    for t in TESTS:\n        try:\n            t()\n            ok += 1\n            print(f"  ✓ {t.__name__}")\n        except Exception:\n            print(f"  ✗ {t.__name__}\\n" + "".join("      " + ln for ln in traceback.format_exc().splitlines(True)[-6:]))\n    print(f"\\nТестов пройдено: {ok} из {len(TESTS)}")\n    sys.stdout.flush()\n    sys.stderr.flush()\n    os._exit(0 if ok == len(TESTS) else 1)\n\n\nif __name__ == "__main__":\n    main()\n'}
TOUCHED = ["main.py", ".gitignore", ".github/workflows/tests.yml"]


def p(rel):
    return os.path.join(ROOT, *rel.split("/"))


def restore(backup):
    for rel in TOUCHED:
        b = os.path.join(backup, *rel.split("/"))
        if os.path.exists(b):
            shutil.copy2(b, p(rel))
    for rel in NEW:
        if os.path.exists(p(rel)):
            os.remove(p(rel))
    print(f"Вернул прежние файлы из {backup}. Копия memory.db тоже там: {os.path.join(backup, 'memory.db')}")


if "--rollback" in sys.argv:
    cands = sorted(d for d in os.listdir(ROOT) if d.startswith("backup_cloudmem_"))
    if not cands:
        sys.exit("Резервной копии нет.")
    restore(p(cands[-1]))
    sys.exit(0)
if "start_memory_autoreview" not in open(p("main.py"), encoding="utf-8").read():
    sys.exit("Сначала поставь apply_step1.py.")
if os.path.exists(p("core/cloud_sync.py")):
    sys.exit("Уже установлено. Проверка: python tests/test_cloud_sync.py; связь: python core/cloud_sync.py")

changed, status = {}, []
for rel, what, old, repl in PATCHES:
    s = changed.get(rel) or open(p(rel), encoding="utf-8").read()
    if s.count(old) == 1:
        changed[rel] = s.replace(old, repl, 1)
        status.append((what, "ok"))
    else:
        changed[rel] = s
        status.append((what, f"НЕ НАЙДЕНО ({s.count(old)})"))
for what, st in status:
    print(f"  {'✓' if st == 'ok' else '!'} {what}" + ("" if st == "ok" else f" — {st}"))
if any(st != "ok" for _, st in status):
    sys.exit("Код выглядит иначе, чем я ожидал — ничего не изменено. Пришли вывод.")

backup = p(time.strftime("backup_cloudmem_%Y%m%d_%H%M%S"))
os.makedirs(backup, exist_ok=True)
for rel in TOUCHED + ["memory.db", "atlas_data.json"]:
    if os.path.exists(p(rel)):
        os.makedirs(os.path.dirname(os.path.join(backup, *rel.split("/"))), exist_ok=True)
        shutil.copy2(p(rel), os.path.join(backup, *rel.split("/")))
print(f"Резервная копия (вместе с memory.db и заметками): {backup}")
for rel, s in list(changed.items()) + list(NEW.items()):
    os.makedirs(os.path.dirname(p(rel)), exist_ok=True)
    with open(p(rel), "w", encoding="utf-8", newline="\n") as f:
        f.write(s)
print("  ✓ core/cloud_sync.py, cloud/supabase_setup.sql, tests/test_cloud_sync.py")

gi = p(".gitignore")
have = open(gi, encoding="utf-8", errors="ignore").read() if os.path.exists(gi) else ""
if "cloud_sync_state.json" not in have:
    with open(gi, "a", encoding="utf-8") as f:
        f.write("\ncloud_sync_state.json\n")
    print("  ✓ .gitignore: cloud_sync_state.json")

suites = [f for f in sorted(os.listdir(p("tests"))) if f.startswith("test_") and f.endswith(".py")]
wf = ("name: tests\n\non:\n  push:\n  pull_request:\n\njobs:\n  atlas:\n    runs-on: ubuntu-latest\n    steps:\n"
      "      - uses: actions/checkout@v4\n      - uses: actions/setup-python@v5\n        with:\n          python-version: \"3.12\"\n"
      "      - run: pip install numpy pillow\n" + "".join(f"      - run: python tests/{s}\n" for s in suites))
os.makedirs(os.path.dirname(p(".github/workflows/tests.yml")), exist_ok=True)
with open(p(".github/workflows/tests.yml"), "w", encoding="utf-8", newline="\n") as f:
    f.write(wf)
print(f"  ✓ автопроверка на GitHub: {len(suites)} наборов тестов")

env = dict(os.environ, PYTHONIOENCODING="utf-8", PYTHONUTF8="1")
for suite in suites:
    r = subprocess.run([sys.executable, p("tests/" + suite)], cwd=ROOT, capture_output=True, text=True, encoding="utf-8",
                       errors="replace", timeout=300, env=env)
    m = re.search(r"Тестов пройдено: (\d+) из (\d+)", r.stdout + r.stderr)
    good = r.returncode == 0 and m and m.group(1) == m.group(2)
    print(f"  {'✓' if good else '✗'} tests/{suite}: {m.group(0) if m else 'итоговой строки нет'}")
    if not good:
        out = (r.stdout + "\n" + r.stderr).splitlines()
        for i, ln in enumerate(out):
            if ln.strip().startswith("✗"):
                print("      " + "\n      ".join(x.rstrip() for x in out[i:i + 7]))
        with open(p("cloudmem_test_output.txt"), "w", encoding="utf-8") as f:
            f.write(r.stdout + "\n" + r.stderr)
        restore(backup)
        sys.exit("✗ Проверка не прошла — всё возвращено.")
print("\nГотово. Дальше — настройка Supabase (инструкция в чате), затем: python core/cloud_sync.py")
